import type { Json, JsonObject } from "../lib/Json";
import type { DistributiveOmit } from "../lib/utils";
import type { LiveFileData } from "./StorageNode";

export type OpCode = (typeof OpCode)[keyof typeof OpCode];
export const OpCode = Object.freeze({
  INIT: 0,
  SET_PARENT_KEY: 1,
  CREATE_LIST: 2,
  UPDATE_OBJECT: 3,
  CREATE_OBJECT: 4,
  DELETE_CRDT: 5,
  DELETE_OBJECT_KEY: 6,
  CREATE_MAP: 7,
  CREATE_REGISTER: 8,
  // TODO: 9 and 10 are used by LiveText, wait until it's merged.
  CREATE_FILE: 11,
});

export namespace OpCode {
  export type INIT = typeof OpCode.INIT;
  export type SET_PARENT_KEY = typeof OpCode.SET_PARENT_KEY;
  export type CREATE_LIST = typeof OpCode.CREATE_LIST;
  export type UPDATE_OBJECT = typeof OpCode.UPDATE_OBJECT;
  export type CREATE_OBJECT = typeof OpCode.CREATE_OBJECT;
  export type DELETE_CRDT = typeof OpCode.DELETE_CRDT;
  export type DELETE_OBJECT_KEY = typeof OpCode.DELETE_OBJECT_KEY;
  export type CREATE_MAP = typeof OpCode.CREATE_MAP;
  export type CREATE_REGISTER = typeof OpCode.CREATE_REGISTER;
  export type CREATE_FILE = typeof OpCode.CREATE_FILE;
}

/**
 * These operations are the payload for {@link UpdateStorageServerMsg} messages
 * only.
 */
export type Op =
  | CreateOp
  | UpdateObjectOp
  | DeleteCrdtOp
  | SetParentKeyOp // Only for lists!
  | DeleteObjectKeyOp;

export type CreateOp =
  | CreateObjectOp
  | CreateRegisterOp
  | CreateMapOp
  | CreateListOp
  | CreateFileOp;

export type UpdateObjectOp = {
  readonly opId?: string;
  readonly id: string;
  readonly type: OpCode.UPDATE_OBJECT;
  readonly data: Partial<JsonObject>;
};

export type CreateObjectOp = {
  readonly opId?: string;
  readonly id: string;
  readonly type: OpCode.CREATE_OBJECT;
  readonly parentId: string;
  readonly parentKey: string;
  readonly data: JsonObject;
  readonly intent?: "set" | "push";
  readonly deletedId?: string;
};

export type CreateListOp = {
  readonly opId?: string;
  readonly id: string;
  readonly type: OpCode.CREATE_LIST;
  readonly parentId: string;
  readonly parentKey: string;
  readonly intent?: "set" | "push";
  readonly deletedId?: string;
};

export type CreateMapOp = {
  readonly opId?: string;
  readonly id: string;
  readonly type: OpCode.CREATE_MAP;
  readonly parentId: string;
  readonly parentKey: string;
  readonly intent?: "set" | "push";
  readonly deletedId?: string;
};

export type CreateRegisterOp = {
  readonly opId?: string;
  readonly id: string;
  readonly type: OpCode.CREATE_REGISTER;
  readonly parentId: string;
  readonly parentKey: string;
  readonly data: Json;
  readonly intent?: "set" | "push";
  readonly deletedId?: string;
};

export type CreateFileOp = {
  readonly opId?: string;
  readonly id: string;
  readonly type: OpCode.CREATE_FILE;
  readonly parentId: string;
  readonly parentKey: string;
  readonly data: LiveFileData;
  readonly intent?: "set" | "push";
  readonly deletedId?: string;
};

export type DeleteCrdtOp = {
  readonly opId?: string;
  readonly id: string;
  readonly type: OpCode.DELETE_CRDT;
};

//
// HACK:
// Disguised as a "DeleteCrdtOp" for a nonexisting node "ACK", this Op that the
// server may return to senders is effectively sent as a backward-compatible
// way to trigger an acknowledgement for Ops that were seen by the server, but
// deliberately ignored.
//
export type IgnoredOp = {
  readonly type: OpCode.DELETE_CRDT; // Not a typo!
  readonly id: "ACK"; // (H)ACK
  readonly opId: string;
};

export function isIgnoredOp(op: ServerWireOp): op is IgnoredOp {
  return op.type === OpCode.DELETE_CRDT && op.id === "ACK";
}

export function isCreateOp<O extends Op>(op: O): op is O & CreateOp {
  return (
    op.type === OpCode.CREATE_OBJECT ||
    op.type === OpCode.CREATE_REGISTER ||
    op.type === OpCode.CREATE_FILE ||
    op.type === OpCode.CREATE_MAP ||
    op.type === OpCode.CREATE_LIST
  );
}

export type SetParentKeyOp = {
  readonly opId?: string;
  readonly id: string;
  readonly type: OpCode.SET_PARENT_KEY;
  readonly parentKey: string;
};

export type DeleteObjectKeyOp = {
  readonly opId?: string;
  readonly id: string;
  readonly type: OpCode.DELETE_OBJECT_KEY;
  readonly key: string;
};

//
// ------------------------------------------------------------------------------
// Wire types for Ops sent over the network
// ------------------------------------------------------------------------------
//

export type HasOpId = { opId: string };

/**
 * Ops sent from client → server. Always includes an opId so the server can
 * acknowledge the receipt.
 */
export type ClientWireOp = Op & HasOpId;
export type ClientWireCreateOp = CreateOp & HasOpId;

/**
 * ServerWireOp: Ops sent from server → client. Three variants:
 * 1. ClientWireOp — Full echo back of our own op, confirming it was applied
 * 2. IgnoredOp — Our op was seen but intentionally ignored (still counts as ack)
 * 3. Op without opId — Another client's op being forwarded to us
 */
export type ServerWireOp =
  | ClientWireOp // "Our" Op echoed back in full to ACK (V7 response)
  | IgnoredOp // "Our" Op was ignored by the server (not forwarded) in v7
  | TheirOp; // "Their" Op (V7 forward)

type TheirOp = DistributiveOmit<Op, "opId"> & { opId?: undefined };
